WITH metrics AS (SELECT id, supplier_name, country, city, rating, PERCENT_RANK() OVER (ORDER BY rating DESC NULLS FIRST) AS rating_percent_rank, LAST_VALUE(city, TRUE) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_city, AVG(rating) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS rating_avg_3_prior FROM suppliers) SELECT id, country, city, rating, rating_avg_3_prior, CASE WHEN city RLIKE '^(Tokyo|Singapore)$' THEN 'PRIORITY' WHEN city RLIKE '^(Bangkok|Chiang Mai)$' THEN 'EXTENDED' ELSE 'OTHER_ZONE' END AS city_zone FROM metrics ORDER BY city DESC, id
